import numpy as np
from sklearn.neighbors import KNeighborsClassifier

def test_predict_setosa():
    result = exercise.predict_iris_class([5.0, 3.5, 1.5, 0.3])
    assert result == 0, f"Expected 0 (setosa), got {result}"

def test_predict_versicolor():
    result = exercise.predict_iris_class([5.8, 2.7, 4.1, 1.3])
    assert result == 1, f"Expected 1 (versicolor), got {result}"

def test_predict_virginica():
    result = exercise.predict_iris_class([6.0, 3.0, 5.5, 2.0])
    assert result == 2, f"Expected 2 (virginica), got {result}"

def test_custom_k_value():
    result = exercise.predict_iris_class([5.1, 3.5, 1.4, 0.2], k=5)
    assert result == 0, f"Expected 0 with k=5, got {result}"

def test_returns_int():
    result = exercise.predict_iris_class([6.3, 3.3, 6.0, 2.5])
    assert isinstance(result, (int, np.integer)), f"Expected int, got {type(result)}"

def test_unknown_sample():
    result = exercise.predict_iris_class([4.5, 2.3, 1.3, 0.1])
    assert isinstance(result, int), f"Expected int, got {type(result)}"
